'use strict';

// MAIN //

class Float16Array {
	constructor(input) {
		if (typeof input === 'number') {
			this._buffer = new Uint16Array(input);
		} else if (Array.isArray(input)) {
			this._buffer = new Uint16Array(input.length);
			for (let i = 0; i < input.length; i++) {
				this._buffer[i] = Float16Array.toFloat16(input[i]);
			}
		} else {
			throw new TypeError('Unsupported constructor argument');
		}
		this.length = this._buffer.length;
	}

	get(index) {
		return Float16Array.fromFloat16(this._buffer[index]);
	}

	set(index, value) {
		this._buffer[index] = Float16Array.toFloat16(value);
	}




  copyWithin(target, start, end) {
		target = target >> 0;
		start = start >> 0;
		end = end === undefined ? this.length : end >> 0;

		const to = target < 0 ? this.length + target : target;
		const from = start < 0 ? this.length + start : start;
		const final = end < 0 ? this.length + end : end;

		const count = Math.min(final - from, this.length - to);
		const direction = from < to && to < (from + count) ? -1 : 1;

		if (direction === -1) {
			for (let i = count - 1; i >= 0; i--) {
				this._buffer[to + i] = this._buffer[from + i];
			}
		} else {
			for (let i = 0; i < count; i++) {
				this._buffer[to + i] = this._buffer[from + i];
			}
		}
		return this;
	}

  entries() {
	return this._entriesGenerator();
}

*_entriesGenerator() {
	for (let i = 0; i < this.length; i++) {
		yield [i, this.get(i)];
	}
}

every(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}
	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (!callback.call(thisArg, value, i, this)) {
			return false;
		}
	}
	return true;
}

fill(value, start = 0, end = this.length) {
	start = start < 0 ? Math.max(this.length + start, 0) : Math.min(start, this.length);
	end = end < 0 ? Math.max(this.length + end, 0) : Math.min(end, this.length);

	for (let i = start; i < end; i++) {
		this.set(i, value);
	}
	return this;
}

filter(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}

	const result = [];
	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			result.push(value);
		}
	}

	return new Float16Array(result);
}

findIndex(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}

	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			return i;
		}
	}
	return -1;
}

find(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}

	for (let i = 0; i < this.length; i++) {
		const value = this.get(i);
		if (callback.call(thisArg, value, i, this)) {
			return value;
		}
	}
	return undefined;
}

forEach(callback, thisArg) {
	if (typeof callback !== 'function') {
		throw new TypeError('callback must be a function');
	}
	for (let i = 0; i < this.length; i++) {
		callback.call(thisArg, this.get(i), i, this);
	}
}

static from(source, mapFn, thisArg) {
	if (source == null) {
		throw new TypeError('source cannot be null or undefined');
	}
	if (mapFn !== undefined && typeof mapFn !== 'function') {
		throw new TypeError('when provided, mapFn must be a function');
	}

	let values = [];
	const iteratorSymbol = typeof Symbol === 'function' && Symbol.iterator;

	if (iteratorSymbol && source[iteratorSymbol]) {
		// Iterable
		const iterator = source[iteratorSymbol]();
		let step;
		while (!(step = iterator.next()).done) {
			values.push(step.value);
		}
	} else if (typeof source.length === 'number') {
		// Array-like
		for (let i = 0; i < source.length; i++) {
			values.push(source[i]);
		}
	} else {
		throw new TypeError('source is not iterable or array-like');
	}

	// Apply mapFn if provided
	if (mapFn) {
		if (thisArg) {
			values = values.map(function(v, i) {
				return mapFn.call(thisArg, v, i);
			});
		} else {
			values = values.map(mapFn);
		}
	}

	// Create new Float16Array from processed values
	const arr = new Float16Array(values.length);
	for (let i = 0; i < values.length; i++) {
		arr.set(i, values[i]);
	}
	return arr;
}
  



	static toFloat16(val) {
		const floatView = new Float32Array(1);
		const intView = new Uint32Array(floatView.buffer);

		floatView[0] = val;
		const x = intView[0];

		const sign = (x >> 16) & 0x8000;
		const exponent = ((x >> 23) & 0xff) - 127;
		const fraction = x & 0x7fffff;

		if (exponent <= -15) {
			// Subnormal
			if (exponent < -24) return sign; // too small => 0
			const sub = (fraction | 0x800000) >> (-exponent - 1);
			return sign | (sub >> 13);
		}

		if (exponent >= 16) {
			// Overflow => Inf
			return sign | 0x7c00;
		}

		const exp = exponent + 15;
		const frac = fraction >> 13;
		return sign | (exp << 10) | frac;
	}

	static fromFloat16(bits) {
		const sign = (bits & 0x8000) << 16;
		let exponent = (bits & 0x7C00) >> 10;
		const fraction = bits & 0x03FF;

		let result;
		if (exponent === 0) {
			// Subnormal number
			if (fraction === 0) {
				result = sign;
			} else {
				exponent = 1;
				while ((fraction & 0x0400) === 0) {
					fraction <<= 1;
					exponent--;
				}
				fraction &= ~0x0400;
				const exp32 = 127 - 15 - exponent;
				const frac32 = fraction << 13;
				result = sign | (exp32 << 23) | frac32;
			}
		} else if (exponent === 0x1F) {
			// Inf or NaN
			result = sign | 0x7F800000 | (fraction << 13);
		} else {
			// Normalized number
			const exp32 = exponent - 15 + 127;
			result = sign | (exp32 << 23) | (fraction << 13);
		}

		const intView = new Uint32Array(1);
		intView[0] = result;
		const floatView = new Float32Array(intView.buffer);
		return floatView[0];
	}
}


// EXPORTS //

module.exports = Float16Array;
